        // @ts-ignore
        const page: Pick<QueryKey<Options<ConnectorsRevisionsListData>>[0], 'body' | 'headers' | 'path' | 'query'> = typeof pageParam === 'object' ? pageParam : {
            query: {
                before: pageParam
            }
        };
        const params = createInfiniteParams(queryKey, page);
